import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider a cyclic necklace with {start_n} through {end_n} beads: for each integer n in this range, take an n-gon whose vertices ("beads") are initially labeled 0. A move consists of choosing two adjacent beads and increasing both their labels by 1. If it is possible, after more than 0 moves, to make all n bead labels equal, define g(n) to be the minimal number of moves needed; otherwise set g(n) = 0. Compute the sum S = sum_{n={start_n}}^{n={end_n}} g(n).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We will generate a nontrivial interval [start_n, end_n] with length between 60 and 400
# to ensure the sum is not trivial but still easily verifiable in O(length) time.
while True:
    lo = rng.randint(50, 300)
    length = rng.randint(60, 400)
    hi = lo + length
    if hi > lo and hi <= 2000:  # keep sizes reasonable
        break
return {"start_n": lo, "end_n": hi}

    def verifier(assign):
# Validate domain
if not isinstance(assign, dict):
    # invalid input structure
    return (False, None)
if 'start_n' not in assign or 'end_n' not in assign:
    # missing required slots
    return (False, None)
L = assign['start_n']
R = assign['end_n']
if not (isinstance(L, int) and isinstance(R, int)):
    return (False, None)
if L < 1 or R < 1 or L > R:
    return (False, None)

# Problem: For each n in [L, R], g(n) is the minimal number of moves to make all labels equal
# on a cycle of n vertices where each move adds 1 to two adjacent vertices.
# Claim (proved in notes):
#   g(n) = n/2 if n is even (achieved by a perfect matching),
#   g(n) = n   if n is odd (achieved by taking all n edges once; no perfect matching exists on odd cycle).

# Compute the sum S = sum g(n) for n in [L, R]
S = 0
for n in range(L, R + 1):
    if n % 2 == 0:
        S += n // 2
    else:
        S += n
return (True, S)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

